def _serialize_mrs(mrs):
    """Serialize a SimpleMRS to surface form."""
    if mrs.predication.is_arg():
        predication = _serialize_lnk(mrs.predication)
    else:
        predication = mrs.predication.surface
    return f'({predication} {_serialize_lnk(mrs.subject)} {_serialize_lnk(mrs.object)})'


def _serialize_mrs_to_surface(mrs):
    """Serialize a SimpleMRS to surface form."""
    return _serialize_mrs(mrs)


def _serialize_mrs_to_surface_with_arg_tags(mrs):
    """Serialize a SimpleMRS to surface form, including argument tags."""
    if mrs.predication.is_arg():
        predication = _serialize_lnk(mrs.predication)
    else:
        predication = mrs.predication.surface
    subject = _serialize_lnk(mrs.subject)
    object = _serialize_lnk(mrs.object)
    return f'({predication} {subject} {object})'


